#!/bin/bash
set -euo pipefail
WEB=/var/www/fusionpbx/app/agent_dashboard
B64_skykin_config_php=''
echo "${B64_skykin_config_php}" | base64 -d > /tmp/skykin_config.php
docker cp /tmp/skykin_config.php skykin-web:$WEB/skykin_config.php
B64_supervisor_php=''
echo "${B64_supervisor_php}" | base64 -d > /tmp/supervisor.php
docker cp /tmp/supervisor.php skykin-web:$WEB/supervisor.php
B64_index_php=''
echo "${B64_index_php}" | base64 -d > /tmp/index.php
docker cp /tmp/index.php skykin-web:$WEB/index.php
B64_data_php=''
echo "${B64_data_php}" | base64 -d > /tmp/data.php
docker cp /tmp/data.php skykin-web:$WEB/data.php
B64_reports_php=''
echo "${B64_reports_php}" | base64 -d > /tmp/reports.php
docker cp /tmp/reports.php skykin-web:$WEB/reports.php
docker exec skykin-web php -r 'opcache_reset();' 2>/dev/null || true
docker exec skykin-web php -r '
require "/var/www/fusionpbx/app/agent_dashboard/skykin_config.php";
$ivr=["direction"=>"inbound","billsec"=>40,"waitsec"=>40,"duration"=>45,"hangup_cause"=>"NORMAL_CLEARING","destination_number"=>"+251116198038","caller_id_number"=>"+251911111111","start_epoch"=>1000,"last_arg"=>"user/203@ahununu","cc_agent_bridged"=>""];
$ring=["direction"=>"inbound","billsec"=>25,"waitsec"=>25,"duration"=>30,"hangup_cause"=>"NORMAL_CLEARING","destination_number"=>"+251116198037","caller_id_number"=>"+251922222222","start_epoch"=>2000,"last_arg"=>"user/202@ahununu","cc_agent_bridged"=>""];
$ok=["direction"=>"inbound","billsec"=>90,"waitsec"=>30,"duration"=>95,"hangup_cause"=>"NORMAL_CLEARING","destination_number"=>"+251116198036","caller_id_number"=>"+251933333333","start_epoch"=>3000,"last_arg"=>"user/203@ahununu","cc_agent_bridged"=>"/203@ahununu"];
echo skykin_cdr_result_label($ivr)," talk=",skykin_cdr_talksec($ivr),"\n";
echo skykin_cdr_result_label($ring)," talk=",skykin_cdr_talksec($ring),"\n";
echo skykin_cdr_result_label($ok)," talk=",skykin_cdr_talksec($ok),"\n";
'
echo DONE
